"use client";
import { ShaderSurface, type ShaderSurfaceOptions } from "./shader-surface";
export interface ImageGlitchProps
  extends Pick<
    ShaderSurfaceOptions,
    | "children"
    | "className"
    | "style"
    | "height"
    | "alt"
    | "duration"
    | "intensity"
    | "speed"
    | "scale"
    | "variant"
    | "maxDpr"
    | "onReady"
  > {
  image: string;
}
/** RGB channel separation, analog scan lines or digital block tearing on pointer/focus. */
export function ImageGlitch(props: ImageGlitchProps) {
  return <ShaderSurface kind="glitch" scale={3} duration={0.5} {...props} />;
}
